	MOVQ src_len+32(FP), CX
	CMPQ CX, $32
	JB whole_1k_stored_short
	LEAQ (R8)(CX*1), DX
	LEAQ (SI)(CX*1), R9
whole_1k_stored_loop:
	CMPQ CX, $64
	JBE whole_1k_stored_tail
	MOVOU (R8), X0
	MOVOU 16(R8), X1
	MOVOU 32(R8), X2
	MOVOU 48(R8), X3
	MOVOU X0, (SI)
	MOVOU X1, 16(SI)
	MOVOU X2, 32(SI)
	MOVOU X3, 48(SI)
	ADDQ $64, R8
	ADDQ $64, SI
	SUBQ $64, CX
	JMP whole_1k_stored_loop
whole_1k_stored_tail:
	CMPQ CX, $32
	JBE whole_1k_stored_last
	MOVOU (R8), X0
	MOVOU 16(R8), X1
	MOVOU X0, (SI)
