whole_1k_stored_short:
	MOVOU (R8), X0
	MOVOU -16(R8)(CX*1), X1
	MOVOU X0, (SI)
	MOVOU X1, -16(SI)(CX*1)
whole_1k_stored_done:
	MOVQ src_len+32(FP), AX
	ADDQ $2, AX
	MOVQ AX, ret+48(FP)
	RET
